using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceUiOperations
{
    public Settings prepare_warp_bake(Control workspace,string id)
    {
        var owner=workspace.Get("document").As<Resource>();var item=_documents.layer_for_id(owner,id);if(item==null||item.Get("warp").AsGodotObject()==null)return new Settings();var temporary=new KiwiImageDocument();var size=(Vector2I)_layers.content_dimensions(item).Ceil();temporary.Set("canvas_size",size);var materials=temporary.Get("live_materials").AsGodotArray();foreach(var material in owner.Get("live_materials").AsGodotArray())materials.Add(material);var copy=_layers.copy_layer(item);copy.Set("parent_id","");copy.Set("position",Vector2.Zero);copy.Set("rotation",0.0);copy.Set("dimensions",(Vector2)size);copy.Set("opacity",1.0);copy.Set("blend",0);copy.Set("mask",default(Variant));copy.Set("clip_to_below",false);copy.Get("effects").AsGodotArray().Clear();var properties=copy.Get("properties").AsGodotDictionary();foreach(string key in new[]{"basis_x","basis_y","flip_x","flip_y","yaw_up_down","yaw_left_right","value_operations","value_basics"})properties.Remove(key);var layers=temporary.Get("layers").AsGodotArray();layers.Add(copy);foreach(var raw in owner.Get("layers").AsGodotArray()){var child=raw.As<Resource>();if(_documents.is_descendant(owner,child.Get("id").AsString(),id))layers.Add(_layers.copy_layer(child));}var renderer=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_renderer.gd").New().As<Node>();workspace.AddChild(renderer);renderer.Call("sync",temporary);return new Settings{["renderer"]=renderer,["temporary"]=temporary,["item"]=item,["id"]=id};
    }
    public void complete_warp_bake(Control workspace,Settings request,Image? image)
    {
        var renderer=request["renderer"].As<Node>();if(GodotObject.IsInstanceValid(renderer))renderer.QueueFree();if(!GodotObject.IsInstanceValid(workspace)||!workspace.IsInsideTree())return;var item=request["item"].As<Resource>();string id=request["id"].AsString();var document=workspace.Get("document").As<Resource>();if(_documents.layer_for_id(document,id)!=item)return;if(image==null){workspace.Get("status").As<Label>().Text="Warp could not be rendered; the layer is unchanged";return;}Action(workspace,()=>{var children=new HashSet<string>(StringComparer.Ordinal);var layers=document.Get("layers").AsGodotArray();foreach(var raw in layers){var child=raw.As<Resource>();if(_documents.is_descendant(document,child.Get("id").AsString(),id))children.Add(child.Get("id").AsString());}for(int index=layers.Count-1;index>=0;index--)if(children.Contains(layers[index].As<Resource>().Get("id").AsString()))layers.RemoveAt(index);var old=_layers.local_transform(item);var extent=(Vector2)request["temporary"].As<Resource>().Get("canvas_size").AsVector2I();item.Set("kind","basic");var texture=ImageTexture.CreateFromImage(image);item.Set("texture",texture);item.Set("paint_base",texture);item.Set("warp",default(Variant));item.Get("live_paint").AsGodotArray().Clear();item.Set("dimensions",extent);item.Set("position",old.Origin-extent*.5f+old.BasisXform(extent*.5f));var properties=item.Get("properties").AsGodotDictionary();foreach(string key in new[]{"noise_image","noise_object","image_path"})properties.Remove(key);});Canvas(workspace).QueueRedraw();workspace.Get("status").As<Label>().Text="Warp baked into layer pixels";
    }
}
